for number in [84, 9973, 15625, 1001, 123456, 48000, 999958, 999999]:
    remaining, divisor = number, 2
    factors = []
    while divisor * divisor <= remaining:
        exponent = 0
        while remaining % divisor == 0:
            remaining //= divisor
            exponent += 1
        if exponent:
            factors.append(f"{divisor}^{exponent}" if exponent > 1 else str(divisor))
        divisor += 1
    if remaining > 1:
        factors.append(str(remaining))
    print(f"{number} = {' * '.join(factors)}")
